                            if 0<=x<H and 0<=y<W and g[x][y]==v and (x,y) not in seen:
                                seen.add((x,y)); stack.append((x,y))
                    rs=[c[0] for c in comp]; cs=[c[1] for c in comp]
                    shapes.append(((max(rs)-min(rs)+1, max(cs)-min(cs)+1), v, min(cs), -min(rs)))
    from collections import deque
    queue={}
    for dims,v,c0,r0 in shapes: queue.setdefault(dims,deque()).append((c0,r0,v))
    for k in queue: queue[k]=deque(sorted(queue[k]))
    flat=[]
    for d,q in queue.items():
        for c0,r0,v in q: flat.append((d,c0,r0,v))

    cells=set((i,j) for i in range(H) for j in range(W) if g[i][j]==8)
    # scale s: side of tiles = min strict-maximal-rect height
    def strict_rects(cs):
        res=[]
        for (i,j) in sorted(cs):
            wmax=1
            while (i,j+wmax) in cs: wmax+=1
            for w in range(1,wmax+1):
                h=1
                while all((i+h,k) in cs for k in range(j,j+w)): h+=1
                if any((i-1,k) in cs for k in range(j,j+w)): continue
                if (i,j-1) in cs: continue
                if (i,j+w) in cs: continue
                res.append((i,j,h,w))
        return res
    s=min(h for _,_,h,_ in strict_rects(cells))

    # tile the cells into s x s tiles
    tiles=[]
    rem=set(cells)
    while rem:
        i,j=min(rem)
        blk={(i+a,j+b) for a in range(s) for b in range(s)}
        assert blk<=rem, (i,j)
        rem-=blk
        tiles.append((i,j))

    multis=sorted([f for f in flat if f[0][0]*f[0][1]>1], key=lambda f:(-f[0][0]*f[0][1], f[2], f[3]))
    singles=sorted([f for f in flat if f[0][0]*f[0][1]==1], key=lambda f:(f[2],f[3]))

    def slots_for(dims, avail):
        sw,sh=dims[1],dims[0]   # dims=(sh,sw)
        rh,rw=sw*s, sh*s
        out=[]
        for (i,j) in sorted(avail):
            if all((i+a,j+b) in avail for a in range(rh) for b in range(rw)):
                out.append((i,j,rh,rw))
        return out

    import itertools
    def solve(idx, avail, plan):
        if idx==len(multis): return plan
        d,c0,r0,v=multis[idx]
        slots=slots_for(d, avail)
        # bottommost first, then leftmost
        for (i,j,rh,rw) in sorted(slots, key=lambda p:(-p[0], p[1])):
            nb=avail-{(i+a,j+b) for a in range(rh) for b in range(rw)}
            r=solve(idx+1, nb, plan+[(i,j,rh,rw,v)])
            if r is not None: return r
        return None
    plan=solve(0, cells, [])
    assert plan is not None
    for (i,j,rh,rw,v) in plan:
        for a in range(rh):
            for b in range(rw):
                g[i+a][j+b]=v
                cells.discard((i+a,j+b))
    # remaining tiles in reading order get singles in queue order
    rem=sorted(t for t in tiles if t[0:2] and (t[0],t[1]) in cells or True)
    remtiles=[]
    for (i,j) in sorted(cells):
        if (i,j) in [(t[0],t[1]) for t in tiles]: remtiles.append((i,j))
    # recompute tile corners remaining
    remtiles=[]
    rem=set(cells)
    while rem:
        i,j=min(rem)
        rem-={(i+a,j+b) for a in range(s) for b in range(s)}
        remtiles.append((i,j))
    for (i,j),f in zip(remtiles, singles):
        for a in range(s):
            for b in range(s):
                g[i+a][j+b]=f[3]
    return g

